"""Parse UEA/UCR ``.ts`` files into (X, y) without touching the raw scale.

The parser is deliberately conservative: it only strips the ``@`` metadata
header and splits each data line on the final ``:`` (the class label). No
per-series normalisation of any kind is performed (requirement R2).
"""

from __future__ import annotations

import sys
from dataclasses import dataclass
from pathlib import Path

import numpy as np

sys.path.insert(0, str(Path(__file__).resolve().parent.parent))

from src import config  # noqa: E402

MISSING_TOKENS = {"?", "NaN", "nan", "NA", "N/A", ""}


@dataclass
class Split:
    """A single train/test split of raw series."""

    X_train: np.ndarray
    y_train: np.ndarray
    X_test: np.ndarray
    y_test: np.ndarray
    source: str = "designated"

    @property
    def n_train(self) -> int:
        return int(self.X_train.shape[0])

    @property
    def n_test(self) -> int:
        return int(self.X_test.shape[0])


def _parse_ts_file(path: Path) -> tuple[np.ndarray, np.ndarray]:
    """Read a ``.ts`` file, returning (X, y) with NaN for missing values."""
    lines = path.read_text(encoding="utf-8").splitlines()

    # Locate the @data marker; everything before it is metadata.
    data_start = 0
    for i, line in enumerate(lines):
        if line.strip().lower() == "@data":
            data_start = i + 1
            break
    else:  # no @data marker: assume the whole file is data
        data_start = 0

    series: list[list[float]] = []
    labels: list[str] = []
    for raw in lines[data_start:]:
        line = raw.strip()
        if not line or line.startswith("#"):
            continue
        if ":" not in line:
            raise ValueError(f"Malformed data line (no ':' label separator) in {path}: {line[:80]}")
        values_part, label = line.rsplit(":", 1)
        values: list[float] = []
        for tok in values_part.split(","):
            tok = tok.strip()
            if tok in MISSING_TOKENS:
                values.append(np.nan)
            else:
                values.append(float(tok))
        series.append(values)
        labels.append(label.strip())

    if not series:
        raise ValueError(f"No data rows found in {path}")

    lengths = {len(s) for s in series}
    if len(lengths) != 1:
        raise ValueError(f"Unequal series lengths in {path}: {sorted(lengths)[:5]}...")

    X = np.asarray(series, dtype=float)
    y = np.asarray(labels, dtype=object)
    return X, y


def load_designated_split(dataset_dir: Path | None = None) -> Split:
    """Load the archive's own train/test split for the configured dataset."""
    dataset_dir = Path(dataset_dir) if dataset_dir else config.DATASET_DIR
    train_path = dataset_dir / f"{config.DATASET}_TRAIN.ts"
    test_path = dataset_dir / f"{config.DATASET}_TEST.ts"
    for p in (train_path, test_path):
        if not p.exists():
            raise FileNotFoundError(f"Missing dataset file: {p}")

    X_train, y_train = _parse_ts_file(train_path)
    X_test, y_test = _parse_ts_file(test_path)
    return Split(X_train, y_train, X_test, y_test, source="designated")


def describe_split(split: Split, name: str = "split") -> str:
    """Human-readable summary used for the intermediate checks."""
    def counts(y: np.ndarray) -> str:
        vals, cnts = np.unique(y, return_counts=True)
        return ", ".join(f"{v}:{c}" for v, c in zip(vals, cnts))

    return (
        f"[{name}] n_train={split.n_train} n_test={split.n_test} "
        f"series_length={split.X_train.shape[1]} "
        f"train_classes={{{counts(split.y_train)}}} "
        f"test_classes={{{counts(split.y_test)}}} "
        f"raw_range=[{np.nanmin(split.X_train):.4g}, {np.nanmax(split.X_train):.4g}] "
        f"n_missing={int(np.isnan(split.X_train).sum() + np.isnan(split.X_test).sum())}"
    )


